import { expect, test } from "../../fixtures";

test.describe("manage vendors", () => {
  test("pagination limits are enforced", { tag: "@VEN-06" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");

    // Act
    const response = await member.get("/api/vendors?limit=101");

    // Assert
    expect(response.status(), await response.text()).toBe(422);
  });
});
